{"command": "python3 -c "
import os, wave, json, subprocess, numpy as np

for amp_val in [1, 4, 8, 16, 32]:
    calls = [
        {'name': 'module_render', 'arguments': {'path': f'/tmp/test_amp_{amp_val}.wav', 'rate': 44100, 'bits': 16, 'amp': amp_val, 'loops': 1}}
    ]
    with open('/tmp/test_amp.json', 'w') as f:
        json.dump(calls, f)
    subprocess.run(['ft2', 'batch', '/tmp/test_amp.json'], stdout=subprocess.DEVNULL)
    if os.path.exists(f'/tmp/test_amp_{amp_val}.wav'):
        with wave.open(f'/tmp/test_amp_{amp_val}.wav', 'r') as wf:
            frames = wf.readframes(wf.getnframes())
            data = np.frombuffer(frames, dtype=np.int16)
            print(f'amp={amp_val}: Max amp={np.abs(data).max()}')
""}

